namespace ProductsApi.Models;

/// <summary>
/// The category a product belongs to.
/// </summary>
public enum ProductCategory
{
    Electronics,
    Clothing,
    Food,
    Books
}

/// <summary>
/// Represents a product in the catalog.
/// </summary>
public class Product
{
    /// <summary>Unique identifier for the product.</summary>
    public int Id { get; set; }

    /// <summary>Display name of the product.</summary>
    public required string Name { get; set; }

    /// <summary>Price in USD.</summary>
    public decimal Price { get; set; }

    /// <summary>Category the product belongs to.</summary>
    public ProductCategory Category { get; set; }

    /// <summary>Timestamp when the product was created.</summary>
    public DateTime CreatedAt { get; set; }
}

/// <summary>
/// Request body for creating a new product.
/// </summary>
public class CreateProductRequest
{
    /// <summary>Display name of the product.</summary>
    public required string Name { get; set; }

    /// <summary>Price in USD. Must be greater than zero.</summary>
    public decimal Price { get; set; }

    /// <summary>Category the product belongs to.</summary>
    public ProductCategory Category { get; set; }
}

using ProductsApi.Models;

namespace ProductsApi.Services;

/// <summary>
/// Defines operations for managing products.
/// </summary>
public interface IProductService
{
    /// <summary>Returns all products.</summary>
    IReadOnlyList<Product> GetAll();

    /// <summary>Returns a product by its ID, or null if not found.</summary>
    Product? GetById(int id);

    /// <summary>Creates a new product and returns it with an assigned ID.</summary>
    Product Create(CreateProductRequest request);
}

using ProductsApi.Models;

namespace ProductsApi.Services;

/// <summary>
/// In-memory implementation of <see cref="IProductService"/>.
/// Data is lost when the application restarts.
/// </summary>
public class InMemoryProductService : IProductService
{
    private readonly List<Product> _products = [];
    private int _nextId = 1;
    private readonly object _lock = new();

    public IReadOnlyList<Product> GetAll()
    {
        lock (_lock)
        {
            return _products.ToList().AsReadOnly();
        }
    }

    public Product? GetById(int id)
    {
        lock (_lock)
        {
            return _products.FirstOrDefault(p => p.Id == id);
        }
    }

    public Product Create(CreateProductRequest request)
    {
        lock (_lock)
        {
            var product = new Product
            {
                Id = _nextId++,
                Name = request.Name,
                Price = request.Price,
                Category = request.Category,
                CreatedAt = DateTime.UtcNow
            };

            _products.Add(product);
            return product;
        }
    }
}

using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using ProductsApi.Models;
using ProductsApi.Services;

namespace ProductsApi.Controllers;

/// <summary>
/// API endpoints for managing products.
/// </summary>
[ApiController]
[Route("api/[controller]")]
[Produces("application/json")]
public class ProductsController : ControllerBase
{
    private readonly IProductService _productService;

    public ProductsController(IProductService productService)
    {
        _productService = productService;
    }

    /// <summary>
    /// Retrieves all products.
    /// </summary>
    /// <returns>A list of all products in the catalog.</returns>
    /// <response code="200">Returns the list of products.</response>
    [HttpGet]
    [EndpointSummary("List all products")]
    [EndpointDescription("Retrieves every product currently stored in the catalog.")]
    [ProducesResponseType(typeof(IReadOnlyList<Product>), StatusCodes.Status200OK)]
    public IActionResult GetAll()
    {
        return Ok(_productService.GetAll());
    }

    /// <summary>
    /// Retrieves a single product by its unique identifier.
    /// </summary>
    /// <param name="id">The unique identifier of the product.</param>
    /// <returns>The requested product.</returns>
    /// <response code="200">Returns the requested product.</response>
    /// <response code="404">No product with the given ID was found.</response>
    [HttpGet("{id:int}")]
    [EndpointSummary("Get a product by ID")]
    [EndpointDescription("Retrieves a single product by its unique numeric identifier.")]
    [ProducesResponseType(typeof(Product), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public IActionResult GetById(int id)
    {
        var product = _productService.GetById(id);
        if (product is null)
            return NotFound();

        return Ok(product);
    }

    /// <summary>
    /// Creates a new product.
    /// </summary>
    /// <param name="request">The product data to create.</param>
    /// <returns>The newly created product.</returns>
    /// <response code="201">The product was created successfully.</response>
    /// <response code="400">The request body is invalid.</response>
    [HttpPost]
    [EndpointSummary("Create a product")]
    [EndpointDescription("Creates a new product in the catalog. The server assigns an ID and creation timestamp.")]
    [ProducesResponseType(typeof(Product), StatusCodes.Status201Created)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public IActionResult Create([FromBody] CreateProductRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Name))
            return BadRequest("Product name is required.");

        if (request.Price <= 0)
            return BadRequest("Price must be greater than zero.");

        var product = _productService.Create(request);
        return CreatedAtAction(nameof(GetById), new { id = product.Id }, product);
    }
}

